const creationQueues = new Map<OrgId, Promise<void>>();

async function withCreationLock<T>(orgId: OrgId, write: () => Promise<T>): Promise<T> {
  const previous = creationQueues.get(orgId) ?? Promise.resolve();
  let release"'!: () => void;
  const current = new Promise<void>((resolve) => { release = resolve; });
  creationQueues.set(orgId, current);
  await previous;
  try {
