    release();
    if (creationQueues.get(orgId) === current) creationQueues.delete(orgId);
  }
}

async function requireCreatableProject(actor: Actor, orgId: OrgId, projectId: ProjectId): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));
  return project;
}

/** Both creation paths count live issues and spend the same workspace bucket. */
async function assertCreationAllowance(project: Project, requested: number): Promise<void> {
  const org = requireFound(await orgRepo.findOrgById(project.orgId), "Organization", project.orgId);
  const used = await issueRepo.countIssues(project.orgId, project.id);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, requested)) {
    throw new Error(`Plan ${org.plan} allows no more issues in project ${project.key}`);
  }
  setOrgPlan(project.orgId, org.plan);
  const verdict = await consumeRateLimit(project.orgId, "issue:create", requested);
  if (!verdict.allowed) {
    throw new Error(`Issue rate limit reached; try again after ${verdict.resetAt}`);
  }
}

export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);
  const issue = await withCreationLock(input.orgId, async () => {
    const project = await requireCreatableProject(actor, input.orgId, input.projectId);
    await assertCreationAllowance(project, 1);
    const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
    return issueRepo.insertIssue(input, actor.userId, number);
  });

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });
  return issue;
}

export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);
  const result = await withCreationLock(input.orgId, async () => {
    const previous = await issueRepo.findIssueImport(input.orgId, input.importKey);
    // Authorize the original project as well when a key is replayed elsewhere.
    const project = await requireCreatableProject(actor, input.orgId, input.projectId);
    if (previous) {
      if (previous.projectId !== project.id) {
        await requireCreatableProject(actor, input.orgId, previous.projectId);
      }
      return previous;
    }
    const parsed = importIssuesSchema.parse(input);
    await assertCreationAllowance(project, parsed.rows.length);
    return issueRepo.insertIssueImport(parsed, actor.userId);
  });

