/**
 * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit, setOrgPlan } from "@/lib/rate-limit";
import { importIssuesSchema } from "@/schemas/issue-import";
import type { ImportIssuesInput } from "@/schemas/issue-import";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";
import type { Issue, IssueBoardColumn, IssueImportResult, IssueWithRelations } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

/** Serialize quota checks and number allocation for the single-writer server. */
const creationQueues = new Map<OrgId, Promise<void>>();

async function withCreationLock<T>(orgId: OrgId, write: () => Promise<T>): Promise<T> {
  const previous = creationQueues.get(orgId) ?? Promise.resolve();
  let release!: () => void;
  const current = new Promise<void>((resolve) => { release = resolve; });
  creationQueues.set(orgId, current);
  await previous;
  try {
    return await write();
  } finally {
    release();
    if (creationQueues.get(orgId) === current) creationQueues.delete(orgId);
  }
}

async function requireCreatableProject(actor: Actor, orgId: OrgId, projectId: ProjectId): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));
  return project;
}

/** Both creation paths count live issues and spend the same workspace bucket. */
async function assertCreationAllowance(project: Project, requested: number): Promise<void> {
  const org = requireFound(await orgRepo.findOrgById(project.orgId), "Organization", project.orgId);
  const used = await issueRepo.countIssues(project.orgId, project.id);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, requested)) {
    throw new Error(`Plan ${org.plan} allows no more issues in project ${project.key}`);
  }
  setOrgPlan(project.orgId, org.plan);
  const verdict = await consumeRateLimit(project.orgId, "issue:create", requested);
  if (!verdict.allowed) {
    throw new Error(`Issue rate limit reached; try again after ${verdict.resetAt}`);
  }
}

export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);
  const issue = await withCreationLock(input.orgId, async () => {
    const project = await requireCreatableProject(actor, input.orgId, input.projectId);
    await assertCreationAllowance(project, 1);
    const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
    return issueRepo.insertIssue(input, actor.userId, number);
  });

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });
  return issue;
}

export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);
  const result = await withCreationLock(input.orgId, async () => {
    const previous = await issueRepo.findIssueImport(input.orgId, input.importKey);
    // Authorize the original project as well when a key is replayed elsewhere.
    const project = await requireCreatableProject(actor, input.orgId, input.projectId);
    if (previous) {
      if (previous.projectId !== project.id) {
        await requireCreatableProject(actor, input.orgId, previous.projectId);
      }
      return previous;
    }
    const parsed = importIssuesSchema.parse(input);
    await assertCreationAllowance(project, parsed.rows.length);
    return issueRepo.insertIssueImport(parsed, actor.userId);
  });

  if (!result.replayed) {
    await emit("issues.imported", {
      ...actorEnvelope(actor),
      projectId: result.projectId,
      importKey: result.importKey,
      issueIds: result.issues.map((issue) => issue.id),
    });
  }
  return result;
}

export async function updateIssue(
  actor: Actor,
  input: UpdateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.updateIssue(input);

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: Object.keys(input).filter(
      (key) => key !== "orgId" && key !== "issueId",
    ),
  });

  return after;
}

/** Status transitions are an `issue:update`, not a separate permission. */
export async function changeIssueStatus(
  actor: Actor,
  input: ChangeIssueStatusInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.status === input.status) return before;

  const after = await issueRepo.setIssueStatus(
    input.orgId,
    input.issueId,
    input.status,
  );

  await emit("issue.status_changed", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    from: before.status,
    to: after.status,
  });

  return after;
}

